function marketOrigin(p){
 if(p.signed)return 'SIGNED · '+(game.clubs[game.selected]?.name||'Your club');
 if(p.fromClubId!==null&&p.fromClubId!==undefined)return game.clubs[p.fromClubId]?.name||'Listed club';
 if(p.youthOriginClubId!==undefined&&p.youthOriginClubId!==null)return 'FREE AGENT · academy: '+(game.clubs[p.youthOriginClubId]?.name||'unknown');
 if(p.releasedByClubId!==undefined&&p.releasedByClubId!==null)return 'FREE AGENT · ex-'+(game.clubs[p.releasedByClubId]?.name||'club');
 return 'FREE AGENT';
}
function cupClub(id){return Number.isInteger(id)&&id>=0?game.clubs[id]?.name||'Unknown club':Number.isInteger(id)&&id<0?'Non-League XI '+(-id):'Not recorded';}
function clubTag(id,away=false){const c=game.clubs[id];if(!c)return esc('Non-League XI');const [one,two]=clubColoursById(game.clubs,id);const bg=away?'linear-gradient(90deg,#fff 50%,#e6e6e6 50%)':`linear-gradient(90deg,${one} 50%,${two} 50%)`;return `<span class="club-label"><span class="club-colour-swatch" aria-label="${away?'Away kit white':'Home club colours'}" style="background:${bg}"></span>${esc(c.name)}</span>`;}
