// Retro coach and scout desk: text is contextual, stable and derived from the current save.
function adviserNotes(){
 const club=me(),t=standings(game,club.division),rank=t.findIndex(x=>x.id===club.id)+1;
 const starters=club.squad.filter(p=>club.lineup.includes(p.id));
 const avg=starters.length?Math.round(starters.reduce((n,p)=>n+p.fitness,0)/starters.length):0;
 const injured=club.squad.filter(p=>p.injured).length;
 const forwards=club.squad.filter(p=>p.pos==='FWD').sort((a,b)=>b.skill-a.skill);
 const defence=club.squad.filter(p=>p.pos==='DEF').sort((a,b)=>b.skill-a.skill);
 const weakest=starters.filter(p=>p.pos!=='GK').sort((a,b)=>a.skill-b.skill)[0];
 const defending=club.division===0&&game.history?.at(-1)?.tables?.[0]?.[0]?.id===club.id;
 const board=club.division===0?(defending?(rank<=3?'We are defending champions. The board expect us to challenge for another First Division title.':'As reigning champions, we expect a stronger defence of our title.'):(rank<=3?'We are in the title race. Keep pushing for the First Division championship.':rank>t.length-5?'Relegation is a concern. The board expects a response.':'Our aim is to strengthen our First Division position.')):(rank<=3?'The board are delighted. Promotion is a realistic ambition.':rank>t.length-5?'We are worried by the league position. The chairman expects better results.':'The chairman is content for now, but he expects progress.');
 const fitness=avg<75?'The lads look tired. Some fresh legs might be wise.':avg<88?'Fitness is adequate, though a few players could use a rest.':'Training has gone well. The players look fit and ready.';
 const attack=forwards[0]?.skill>=80?'Our lead striker is in fine shape on paper. We should give him service.':'We could do with more firepower up front.';
 const back=defence[0]?.skill>=80?'The defensive unit has a dependable leader.':'I would have another look at the defence before Saturday.';
 const injury=injured?`${injured} player${injured===1?' is':'s are'} currently injured. Check the team sheet.`:'Good news: there are no injuries to report.';
 return {rank,avg,board,fitness,attack,back,injury,weakest};
}
