 if(!p)return bookSpread('MATCHDAY PROGRAMME','FROM THE EDITOR',`<p class="book-small">The programme kiosk opens ahead of home fixtures. Notable programmes will also be kept here after the final whistle.</p>`, 'BACK ISSUES','THE PROGRAMME COLLECTION','<p class="book-small">No programmes in the archive yet.</p>');
