let groundNight=false,groundClubId=0;
function office(){const c=me(),t=standings(game,c.division),rank=t.findIndex(x=>x.id===c.id)+1,fx=game.fixtures[game.round]?.find(x=>x.includes(c.id)),opp=fx?game.clubs[fx[0]===c.id?fx[1]:fx[0]]:null;const text=game.status==='finished'?'Season finished — visit Season Review to see who went up and down.':opp?`${fx[0]===c.id?'HOME':'AWAY'} v ${esc(opp.name)}`:'No league fixture this week';return `<div class="notice game-world-banner">WORLD: ${esc(CAREER_MODES[game.careerMode]||CAREER_MODES.fictional)} ${game.careerMode?.startsWith('historical')?'· PARTIAL RESEARCH / SIMULATED RATINGS':''}</div><div class="notice book-discovery"><strong>YOUR COACH AND SCOUT ARE WAITING.</strong> <button data-nav="notebook">OPEN MANAGER'S NOTEBOOK</button> <span>Read reports, see this week's offers, and sign players from the book.</span></div><div class="match-banner league-banner">${game.status==='finished'?'SEASON COMPLETE — REVIEW RESULTS AND START NEXT SEASON':'NEXT FIXTURE · LEAGUE · '+esc(divName(c.division))}</div>${game.manager&&!game.manager.employed?'<div class="notice error">YOU HAVE BEEN SACKED. Visit Manager’s Office to find your next club.</div>':''}${game.status==='finished'?'<div class="notice"><strong>Season complete!</strong> See the Season Review and click START NEXT SEASON once.</div><button data-action="nextseason">START NEXT SEASON</button>':''}<div class="stats">${[['CLUB',c.name],['DIVISION',divName(c.division)],['POSITION',rank+' / '+t.length],['WEEK',game.round+' / 46'],['TRANSFER FUNDS',money(c.budget)],['CASH',money(c.money)]].map(([label,v])=>`<div class="stat"><span class="label">${label}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="grid">${card('NEXT LEAGUE MATCH',`<div class="big">${text}</div><p>Formation: ${c.formation} · Tactic: ${c.tactic}</p><button data-nav="${game.status==='finished'?'review':'match'}">${game.status==='finished'?'SEASON REVIEW':'MATCH DAY'}</button>`)}${card('CHAIRMAN’S OFFICE',`<p>${rank<=4?'An excellent league position. Keep pushing!':rank>t.length-5?'The board expects improvement. Relegation is a real threat.':'We expect steady progress and careful spending.'}</p><p>Squad: ${c.squad.length} · Wage bill: ${money(c.squad.reduce((s,p)=>s+p.wage,0))} per week.</p><button class="secondary" data-nav="cups">VIEW THE CUPS</button>`)}</div>${card('LATEST NEWS',game.messages.slice(0,9).map(t=>`<div class="event">${esc(t)}</div>`).join(''))}`;}
function sortedSquad(players){const order=['GK','DEF','MID','FWD'],sorters={position:(a,b)=>order.indexOf(a.pos)-order.indexOf(b.pos)||b.skill-a.skill,ability:(a,b)=>b.skill-a.skill,fitness:(a,b)=>b.fitness-a.fitness,morale:(a,b)=>b.morale-a.morale,goals:(a,b)=>b.goals-a.goals,age:(a,b)=>(b.age??25)-(a.age??25),form:(a,b)=>(b.form??6.5)-(a.form??6.5),value:(a,b)=>b.value-a.value,name:(a,b)=>a.name.localeCompare(b.name)};return [...players].sort((a,b)=>(squadDirection==='asc'?-1:1)*sorters[squadSort](a,b)||a.id-b.id);}
function pitch(c){const order=['FWD','MID','DEF','GK'];return `<div class="formation-layout"><div class="formation-pitch" aria-label="Your selected eleven arranged by formation">${order.map(pos=>{const starters=c.squad.filter(p=>p.pos===pos&&c.lineup.includes(p.id)).sort((a,b)=>b.skill-a.skill);return `<div class="formation-row">${starters.map(p=>`<button class="pitch-player ${pitchPick===p.id?'pitch-selected':''}" data-pitch="${p.id}" title="Replace ${esc(p.name)}"><span class="shirt">${pos==='GK'?'🧤':'●'}</span><span class="player-name">${esc(p.name)}</span><small>${pos} · ${p.skill}</small></button>`).join('')}</div>`;}).join('')}</div><div class="pitch-side"><h3>REPLACE A PLAYER</h3>${pitchPick===null?'<p>Select a player on the pitch to choose an available replacement in the same position.</p>':(()=>{const old=c.squad.find(p=>p.id===pitchPick);if(!old)return '<p>Choose a player.</p>';const bench=c.squad.filter(p=>p.pos===old.pos&&!c.lineup.includes(p.id));return `<p>Replacing <strong>${esc(old.name)}</strong> (${old.pos})</p>${bench.length?bench.map(p=>`<button class="bench-option" data-replace="${p.id}" ${p.injured?'disabled':''}>${esc(p.name)} <span>${p.skill} skill · ${p.fitness}% fit ${p.injured?'· INJURED':''}</span></button>`).join(''):'<p>No available players in this position.</p>'}<button class="secondary" data-action="cancelpick">CANCEL</button>`;})()}<p class="hint">On the pitch, players are arranged in formation rows. Only same-position substitutions are allowed in this version.</p></div></div>`;}
function squad(){const c=me(),rows=sortedSquad(c.squad);return card('FORMATION & INSTRUCTIONS',`<div class="controls"><label>Formation <select id="formation">${Object.keys(FORMATIONS).map(f=>`<option ${f===c.formation?'selected':''}>${f}</option>`).join('')}</select></label><label>Approach <select id="tactic">${['Defend','Balanced','Attack'].map(f=>`<option ${f===c.tactic?'selected':''}>${f}</option>`).join('')}</select></label><button data-action="autolineup">AUTO PICK BEST XI</button><button class="secondary" data-action="assistantlineup" title="Select a balanced starting eleven using skill, fitness, morale, form and experience">ASSISTANT MANAGER PICK</button></div>${game.careerMode?.startsWith('historical')&&game.season===1989&&game.round===0?'<button class="secondary" data-action="recalibrate-historical">FIX HISTORICAL PLAYER RATINGS (v1.9.7 SAVES)</button>':''}<p class="hint">Best XI selects by ability. <strong>${esc(staffReport(game).assistant.title)}:</strong> ${esc(staffReport(game).assistant.description)} Injured players are excluded.</p><div class="notice ${validLineup(c)?'':'error'}">${validLineup(c)?'Starting XI ready: 11/11 selected.':'Starting XI incomplete: '+c.lineup.length+'/11 selected.'}</div>`)+card('FORMATION PITCH',pitch(c))+card('PLAYERS — SELECT YOUR STARTING ELEVEN',`<div class="squad-toolbar"><label>Sort by <select id="squadsort">${[['position','Position'],['ability','Ability'],['fitness','Fitness'],['morale','Morale'],['goals','Goals'],['age','Age'],['form','Form'],['value','Value'],['name','Name']].map(([id,title])=>`<option value="${id}" ${squadSort===id?'selected':''}>${title}</option>`).join('')}</select></label><label>Order <select id="squaddirection"><option value="desc" ${squadDirection==='desc'?'selected':''}>Default</option><option value="asc" ${squadDirection==='asc'?'selected':''}>Reverse</option></select></label></div><div class="scroll"><table><thead><tr><th>Start</th><th>Name</th><th>Pos</th><th class="num">Age</th><th class="num">Skill</th><th class="num">Form</th><th class="num">Apps</th><th class="num">Assists</th><th class="num">Fit</th><th class="num">Morale</th><th class="num">Goals</th><th class="num">Value</th></tr></thead><tbody>${rows.map(p=>`<tr class="${c.lineup.includes(p.id)?'me':''}"><td><input type="checkbox" data-player="${p.id}" ${c.lineup.includes(p.id)?'checked':''} ${p.injured?'disabled':''}></td>${cell(esc(p.name)+(p.injured?' · INJ':''))}${cell(p.pos)}${cell((p.age??'–')+(game.careerMode==='historical'&&p.historicalVerified&&p.ageEstimated?'~':''),'num')}${cell(p.skill,'num')}${cell((p.form??6.5).toFixed(1),'num')}${cell(p.appearances??0,'num')}${cell(p.assists??0,'num')}${cell(p.fitness,'num')}${cell(p.morale,'num')}${cell(p.goals,'num')}${cell(money(p.value),'num')}</tr>`).join('')}</tbody></table></div><p class="hint">Checkboxes can also replace the lowest-rated starter in the same position. In historical research preview, ~ after an age means estimated rather than verified; player abilities are gameplay ratings.</p>`);}
function tableHTML(rows,selected=true){return `<div class="scroll"><table><thead><tr><th>Official #</th><th>Club</th>${['P','W','D','L','GF','GA','GD','Pts'].map(x=>`<th class="num">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${selected&&r.id===game.selected?'me':''}">${cell(r.rank)}${cell(`<button class="league-club-link" data-inspect-club="${r.id}" aria-label="View squad of ${esc(r.name)}">${clubTag(r.id)}</button>`)}${[r.p,r.w,r.d,r.l,r.gf,r.ga,r.gd,r.pts].map(n=>cell(n,'num')).join('')}</tr>`).join('')||'<tr><td colspan="10">No clubs match your search.</td></tr>'}</tbody></table></div>`;}
function inspectedSquad(){
 const c=game.clubs[inspectedClubId];if(!c)return card('CLUB SQUAD','<p>Club not found.</p>');
 const order={GK:0,DEF:1,MID:2,FWD:3};
 const players=[...c.squad].sort((a,b)=>(order[a.pos]??9)-(order[b.pos]??9)||b.skill-a.skill||a.name.localeCompare(b.name));
 const historical=game.careerMode==='historical';
 const squadList=players.map(p=>`<tr><td>${esc(p.name)}${p.historicalAgeEstimated?' <span title="Date of birth not verified">~</span>':''}</td><td>${esc(p.pos)}</td><td class="num">${p.age??'—'}</td><td class="num">${p.skill}</td><td class="num">${p.fitness}%</td><td class="num">${p.form??'—'}</td><td class="num">${p.goals??0}</td></tr>`).join('');
 return `<div class="controls"><button data-action="backleague" class="secondary">◀ BACK TO LEAGUE TABLE</button></div>`+card('CLUB SQUAD — '+esc(c.name),`<p>${clubTag(c.id)} · ${esc(divName(c.division))} · ${players.length} players</p>${c.id===game.selected?'':`<div class="rival-manager-card"><strong>OPPOSITION MANAGER: ${esc(managerForClub(game,c.id).name)}</strong><span>${esc(managerForClub(game,c.id).style)}</span></div>`}<p class="hint">${historical?'Historical research: season-associated player names for all 92 clubs. Current squads can change through transfers and youth development. Player ratings are simulated; August 1989 registrations are not fully certified.':'This is the club’s current in-game squad, including transfers and academy promotions.'} Click another club in the league table to inspect its squad.</p><div class="scroll"><table class="club-squad-table"><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th>Ability</th><th>Fitness</th><th>Form</th><th>Goals</th></tr></thead><tbody>${squadList}</tbody></table></div>`);
}
function league(){if(inspectedClubId!==null)return inspectedSquad();const d=leagueDivision??me().division;const rows=sortLeagueRows(standings(game,d),leagueSort,leagueOrder,leagueQuery);return card('FOOTBALL LEAGUE TABLES',`<div class="printer-heading">FOOTBALL LEAGUE SERVICE · RESULTS AND TABLES · ${game.season}–${String(game.season+1).slice(-2)}</div><div class="squad-toolbar league-toolbar"><label>Division <select id="leaguediv">${DIV_NAMES.map((v,i)=>`<option value="${i}" ${i===d?'selected':''}>${v}</option>`).join('')}</select></label><label>Sort by <select id="leaguesort">${[['pts','Points'],['rank','League position'],['gd','Goal difference'],['gf','Goals scored'],['ga','Goals conceded'],['w','Wins'],['d','Draws'],['l','Losses'],['p','Played'],['name','Club name']].map(([key,label])=>`<option value="${key}" ${key===leagueSort?'selected':''}>${label}</option>`).join('')}</select></label><label>Order <select id="leagueorder"><option value="desc" ${leagueOrder==='desc'?'selected':''}>Highest first</option><option value="asc" ${leagueOrder==='asc'?'selected':''}>Lowest first</option></select></label><label>Club filter <input id="leaguequery" value="${esc(leagueQuery)}" placeholder="Search clubs..." aria-label="Filter league clubs"></label></div><p class="hint">Official league position stays fixed while you sort. Three points for a win · League ranking is by points, goal difference and goals scored.</p><div class="vidiprinter">${tableHTML(rows)}</div><p class="hint">${d===0?'Bottom three relegated.':d===1||d===2?'Top two promoted automatically; third promotion via four-club play-off.': 'Top three promoted automatically; fourth promotion via four-club play-off.'} ${d===2?'Bottom four relegated.':d===1?'Bottom three relegated.':''}</p>`);}
function recordSpread(leftTitle,rightTitle,left,right,numbers=['17','18']){
 return `<div class="desk-caption">PROJECT 1989 · THE MANAGER'S RECORDS <span>${game.season}–${String(game.season+1).slice(-2)}</span></div><div class="notebook record-spread"><section class="book-page left-page"><div class="book-margin">${numbers[0]} / ${leftTitle.toUpperCase()}</div>${left}</section><section class="book-page right-page"><div class="book-margin">${numbers[1]} / ${rightTitle.toUpperCase()}</div>${right}</section></div>`;
}
function fixtures(){
 const c=me(),remaining=game.fixtures.slice(game.round).filter(w=>w.some(([h,a])=>h===c.id||a===c.id));
 const home=remaining.filter(w=>w.some(([h])=>h===c.id)).length,away=remaining.length-home;
 const streak=fixtureStreak(game,c.id);
 const repaired=game.calendarRebalanced?.season===game.season;
 const warning=streak>=5?`<p class="book-small" style="color:#933c26"><strong>Fixture warning:</strong> This career carries a ${streak}-match home/away streak. It may be an older saved calendar.</p>`:'<p class="book-small">Home and away fixtures are spread through the season.</p>';
 const left=`<div class="page-heading">FIXTURE BOOK</div><div class="book-subtitle">${esc(c.name)} · ${esc(divName(c.division))}</div><p class="type-quote">“Every league ground presents a different test, home or away.”</p><div class="paper-row">League matches remaining<strong>${remaining.length}</strong></div><div class="paper-row">Remaining at home<strong>${home}</strong></div><div class="paper-row">Remaining away<strong>${away}</strong></div>${warning}<div class="book-note"><strong>CALENDAR REPAIR</strong><small>${repaired?`Last repaired in week ${game.calendarRebalanced.week}; ${game.calendarRebalanced.changes} fixture pair${game.calendarRebalanced.changes===1?'':'s'} adjusted.`:'If you have inherited an all-away calendar, rebalance the remaining matches without altering completed results.'}</small></div><div class="book-foot"><button data-action="repair-fixtures" ${game.status!=='active'||game.round>=46?'disabled':''}>REBALANCE REMAINING FIXTURES</button></div><p class="book-small">Back up your career before repairing. This changes only unplayed home/away assignments; opponents and matchweeks stay the same.</p>`;
 const right=`<div class="page-heading">THE FIXTURE LIST</div><div class="book-subtitle">SEASON ${game.season}–${String(game.season+1).slice(-2)} · WEEK ${game.round+1}</div><label class="book-small">Matchweek <select id="roundselect">${game.fixtures.map((_,i)=>`<option value="${i}" ${i===Math.min(game.round,45)?'selected':''}>Week ${i+1}</option>`).join('')}</select></label><div id="fixturelist" class="fixture-book-list"></div><p class="book-small">First Division: 38 league matches. Other divisions: 46. The calendar uses simplified dates.</p>`;
 return recordSpread('Fixture Diary','Weekly Fixtures',left,right,['17','18']);
}
function showFixtures(week){const el=document.getElementById('fixturelist');if(!el)return;const pair=game.fixtures[week].filter(([h])=>game.clubs[h].division===me().division),resultMap=new Map(game.results.map(x=>[x.home+':'+x.away,x]));el.innerHTML=`<div class="scroll"><table><thead><tr><th>Home</th><th class="num">Score</th><th>Away</th></tr></thead><tbody>${pair.length?pair.map(([h,a])=>{const r=resultMap.get(h+':'+a);return `<tr class="${h===game.selected||a===game.selected?'me':''}">${cell(clubTag(h))}${cell(r?`${r.hg} – ${r.ag}`:'v','num')}${cell(clubTag(a,true))}</tr>`;}).join(''):'<tr><td colspan="3">No division fixtures scheduled this week.</td></tr>'}</tbody></table></div>`;}
function cups(){return Object.values(game.cups).map(cup=>card(cup.name.toUpperCase(),`<div class="cup-retro-heading"><span>★</span><strong>${esc(cup.name.toUpperCase())}</strong><span>★</span></div><div class="stats"><div class="stat"><span class="label">STAGE</span><strong>${cup.winner===null?cupRoundName(cup.name,cup.stage+1):'Completed'}</strong></div><div class="stat"><span class="label">WINNER / REMAINING</span><strong>${cup.winner!==null?esc(cupClub(cup.winner)):cup.entrants.length+' clubs'}</strong></div></div><p class="hint">${cup.name==='FA Cup'?'Third and Fourth Division clubs start first; First and Second Division clubs join in Round 3.':'Lower divisions enter first; higher divisions enter in the next round.'} Single-match knockout with penalty shootouts in this alpha; historical replays and two-legged ties are not yet modelled.</p>${cup.completed.slice(-2).reverse().map(round=>`<h3>${esc(cupRoundName(cup.name,round.round).toUpperCase())}</h3><div class="scroll"><table><tbody>${round.matches.filter(m=>m.home===game.selected||m.away===game.selected).map(m=>`<tr>${cell(m.home>=0?clubTag(m.home):esc(cupClub(m.home)))}${cell(`${m.hg}–${m.ag}${m.penalties?' (pens)':''}`)}${cell(m.away>=0?clubTag(m.away,true):esc(cupClub(m.away)))}</tr>`).join('')||'<tr><td>No fixture involving your club in this round.</td></tr>'}</tbody></table></div>`).join('')||'<p>The competition has not yet started.</p>'}`)).join('');}
function review(){
 if(!game.history?.length)return card('SEASON REVIEW','<p>No completed season yet. Finish a season to see champions, promotions, relegations and cup winners.</p>');
 const h=game.history.at(-1);
 const clubName=id=>Number.isInteger(id)?esc(cupClub(id)):'Not recorded';
 const clubsList=ids=>Array.isArray(ids)&&ids.length?ids.map(clubName).join(', '):'Not recorded';
 const divisions=DIV_NAMES.map((name,d)=>{
  const champion=h.tables?.[d]?.[0]?.id;
  const promoted=d?`<p>Promoted: ${clubsList(h.promote?.[d])}</p><p>Play-off winners: ${clubName(h.playoffs?.[d]?.winner)}</p>`:'';
  const relegated=d<3?`<p>Relegated: ${clubsList(h.relegate?.[d])}</p>`:'';
  return `<div><h3>${esc(name)}</h3><p>Champions: <strong>${clubName(champion)}</strong></p>${promoted}${relegated}</div>`;
 }).join('');
 const winners=Object.entries(h.cupWinners||{}).map(([name,id])=>`<p>${esc(name)}: <strong>${clubName(id)}</strong></p>`).join('')||'<p>Cup winners not recorded for this season.</p>';
 const editions=game.history.filter(s=>s.edition).slice().reverse();
 const chosen=editions.find(s=>s.season===editionSeason)||editions[0];
 const e=chosen?.edition;
 const archive=editions.length>1?`<div class="edition-archive"><strong>BACK ISSUES</strong> ${editions.map(s=>`<button class="${s===chosen?'selected-edition':'secondary'}" data-season-edition="${s.season}">${s.season}–${String(s.season+1).slice(-2)}</button>`).join('')}</div>`:'';
 const voice=e&&editionVoice!=='national'?e.perspectives?.[editionVoice]:null;
 const paper=e?(voice?.paper||'THE FOOTBALL LEAGUE GAZETTE'):'';
 const articles=e?(voice?.articles||e.articles):[];
 const headline=e?(voice?.headline||e.headline):'';
 const switches=e?.perspectives?`<div class="edition-voices" role="group" aria-label="Newspaper perspective">${[['national','NATIONAL GAZETTE'],['fans','SUPPORTERS’ VOICE'],['regional','LOCAL HERALD']].map(([key,label])=>`<button data-edition-voice="${key}" class="${editionVoice===key?'selected-edition':'secondary'}" aria-pressed="${editionVoice===key}">${label}</button>`).join('')}</div>`:'';
 const special=e?`${switches}<section class="season-special season-special-${esc(editionVoice)}" aria-label="Season newspaper special"><div class="season-special-masthead">${esc(paper)}</div><div class="season-special-kicker">END OF SEASON · SPECIAL EDITION · ${e.season}–${String(e.season+1).slice(-2)}</div><h2>${esc(headline)}</h2><p class="season-special-subtitle">${esc(e.clubName)} · ${esc(e.outcome)}</p>${articles.map(a=>`<section class="season-special-article"><h3>${esc(a.heading)}</h3><p>${esc(a.body)}</p></section>`).join('')}<div class="season-special-footer">YOUR CLUB. YOUR DECISIONS. YOUR LEGACY.</div></section>`:'<p>Earlier seasons do not have a saved newspaper edition. Complete another season to create one.</p>';
 return card(`${h.season}–${String(h.season+1).slice(-2)} SEASON REVIEW`,`<div class="season-review-edition">${archive}${special}</div><details class="season-archive-facts"><summary>OFFICIAL LEAGUE RECORDS AND CUP WINNERS</summary><div class="grid">${divisions}</div><h3>CUP WINNERS</h3>${winners}</details><p class="hint">Promotion uses the 1989–90 league pattern. The First Division remains 20 clubs in future seasons; Conference relegation and the historical 1990–91 expansion are not yet simulated.</p>${game.status==='finished'?'<button data-action="nextseason">START NEXT SEASON</button>':''}`);
}
function gameReport(){const reports=game.matchReports||[];return reports[Math.max(0,Math.min(reportIndex,reports.length-1))]||game.lastMatch||null;}
function competitionLabel(m){return m.competition==='LEAGUE'?`${divName(m.division??me().division)} · LEAGUE`:`${m.competition||m.name||'CUP'}${m.round?' · '+cupRoundName(m.competition||m.name,m.round):''}`;}
function reportTeam(id,away=false){return id<0?esc('Non-League XI '+(-id)):clubTag(id,away);}
function eventHTML(e){return `<div class="event ${e.type==='goal'?'goal':''}"><strong>${e.minute}'</strong> <span class="event-type">${{goal:'⚽ GOAL',chance:'◯ CHANCE',yellow:'🟨 BOOKING',injury:'✚ INJURY',kickoff:'KICK-OFF',halftime:'HALF-TIME',fulltime:'FULL-TIME'}[e.type]||esc(e.type)}</span> · ${e.team===null?'MATCH OFFICIALS':reportTeam(e.team)}<div class="commentary">${esc(e.text||e.scorer||'Chance goes begging')}</div></div>`;}
function matchStats(r){if(!r?.stats)return '<p class="hint">Detailed statistics are available for league and new cup matches in this version.</p>';return `<div class="match-stats"><h3>MATCH STATISTICS</h3>${Object.entries(r.stats).map(([key,nums])=>`<div class="stat-row"><strong>${nums[0]}</strong><span>${esc({shots:'Shots',onTarget:'On Target',possession:'Possession %',corners:'Corners',fouls:'Fouls'}[key]||key)}</span><strong>${nums[1]}</strong></div>`).join('')}</div>`;}
function match(){
 const c=me(),fx=game.fixtures[game.round]?.find(x=>x.includes(c.id)),reports=game.matchReports||[],r=gameReport(),isActive=game.status==='active';
 const cupWeeks=['FA Cup','League Cup'].filter(name=>({ 'FA Cup':[8,12,16,21,26,31,36,41,45],'League Cup':[2,6,11,18,25,33,40,44]})[name].includes(game.round));
 let upcoming='';
 const rivalOpponent=fx?game.clubs[fx[0]===c.id?fx[1]:fx[0]]:null;
 const derby=rivalOpponent?rivalryFor(game,c.id,rivalOpponent.id):null;
 const rivalInfo=rivalOpponent?`<div class="rival-manager-card"><strong>OPPOSITION MANAGER: ${esc(managerProfile(game,rivalOpponent.id).name)}</strong><span>${esc(managerProfile(game,rivalOpponent.id).style)}${derby?' · '+esc(derby.name):''}</span><small>${esc(managerCareerNotes(game,rivalOpponent.id).slice(1).join(' · '))}</small></div>`:'';
 if(!game.manager?.employed)upcoming='<div class="notice error">You are currently unemployed. Find another club in Manager’s Office to resume playing.</div><button data-nav="manager">VIEW JOB VACANCIES</button> <button data-action="advance-unemployed" class="secondary">ADVANCE CALENDAR</button>'; 
 else if(!isActive)upcoming='<div class="notice">The season is finished. Your next step is the Season Review.</div><button data-action="nextseason">START NEXT SEASON</button><button class="secondary" data-nav="review">SEASON REVIEW</button>';
 else upcoming=`<div class="match-banner league-banner">${fx?'UP NEXT · LEAGUE · '+esc(divName(c.division)):'NO LEAGUE FIXTURE THIS WEEK'} · WEEK ${game.round+1}</div>${fx?`<div class="score">${reportTeam(fx[0])} <span class="versus">VS</span> ${reportTeam(fx[1],true)}</div>`:'<p>Your team has a free league week.</p>'}${cupWeeks.length?`<div class="match-banner cup-banner">CUP ACTION ALSO THIS WEEK: ${cupWeeks.join(' + ')}</div><p class="hint">Cup draws and results are processed alongside the league round. If your club is involved, its cup match will appear as a separate labelled report below.</p>`:''}${rivalInfo}${fx&&fx[0]===c.id?'<div class="controls"><button data-book="programme">READ MATCHDAY PROGRAMME</button></div>':''}<p>Formation: ${esc(c.formation)} · Tactic: ${esc(c.tactic)}</p><div class="notice ${validLineup(c)?'':'error'}">${validLineup(c)?'Starting XI confirmed.':'Your starting XI is incomplete. Please select a valid eleven.'}</div><div class="controls"><button data-action="play" ${!validLineup(c)?'disabled':''}>QUICK RESULT · ADVANCE WEEK</button><button data-action="watch" class="secondary" ${!validLineup(c)?'disabled':''}>PLAY & WATCH MATCH</button></div>`;
 let review='';
 if(r){const n=reports.length,idx=Math.max(0,Math.min(reportIndex,n-1)),stat=r.stats||null;review=`<div class="report-head"><div class="match-banner ${r.competition==='LEAGUE'?'league-banner':'cup-banner'}">${esc(competitionLabel(r))} · ${r.competition==='LEAGUE'?'WEEK '+(r.week||game.round):'CUP TIE'}</div><div class="match-clock-main" id="live-clock">${watch?"0′ · KICK-OFF":"MATCH REPLAY"}</div><div class="big-score"><span>${reportTeam(r.home)}</span><strong id="live-score" aria-live="polite">${watch?"0 – 0":`${r.hg} – ${r.ag}`}</strong><span>${reportTeam(r.away,true)}</span></div>${r.penalties&&!watch?'<p class="hint">Drawn after normal time · decided on penalties</p>':''}</div><div class="controls">${n>1?`<button class="secondary" data-action="prevreport" ${idx<=0?'disabled':''}>◀ PREVIOUS REPORT</button><span class="report-counter">Report ${idx+1} of ${n}</span><button class="secondary" data-action="nextreport" ${idx>=n-1?'disabled':''}>NEXT REPORT ▶</button>`:''}</div><div class="controls"><button data-action="replay">▶ WATCH HIGHLIGHTS</button><button class="secondary" data-action="next-event">NEXT EVENT</button><button class="secondary" data-action="all-events">FULL COMMENTARY</button><button class="secondary" data-action="stop-replay">STOP</button><label>Speed <select id="replayspeed"><option value="2500">Slow</option><option value="1450" selected>Normal</option><option value="700">Fast</option></select></label></div><div class="match-replay-grid"><div class="retro-broadcast"><div class="retro-broadcast-top"><span>PROJECT 1989 · UNDER THE FLOODLIGHTS</span><span>${esc(r.venue||groundProfile(game.clubs[r.home]).name)} · ${r.night?'FLOODLIT MATCH':'MATCH DAY'}</span></div><canvas id="retrocanvas" width="320" height="180" aria-label="Retro pitch showing a schematic replay of the current recorded match incident" role="img"></canvas><p class="retro-scene-note">Stylised incident replay · not a live tactical simulation</p></div><div class="match-focus" id="matchfocus" aria-live="polite"><div class="match-focus-icon">📻</div><strong>MATCH HIGHLIGHTS</strong><p>Select WATCH HIGHLIGHTS to replay the major incidents in chronological order.</p><small>${watch?"Score updates as goals happen":`${reportTeam(r.home)} ${r.hg}–${r.ag} ${reportTeam(r.away)}`}</small></div></div><div id="replay-detail" ${watch?"hidden":""}>${matchStats(r)}<div class="match-timeline-head"><h3>MATCH INCIDENTS</h3><small>Select an incident to replay it. The pitch and current commentary stay in view.</small></div><div id="events" class="match-timeline" aria-label="Match incident timeline">${r.events.map((e,i)=>`<button class="timeline-item" data-incident="${i}" type="button"><strong>${e.minute}′</strong><span>${esc(e.type.toUpperCase())}</span><small>${esc((e.text||'').slice(0,90))}</small></button>`).join('')}</div></div>`;}
 return card('MATCH CENTRE',upcoming)+(r?card('MATCH REPORT & HIGHLIGHTS',review):'');
}
function transfers(){
 const c=me(),order=['GK','DEF','MID','FWD'];let candidates=transferCandidates(game);
 if(transferPos!=='ALL')candidates=candidates.filter(p=>p.pos===transferPos);
 candidates.sort((a,b)=>transferSort==='position'?order.indexOf(a.pos)-order.indexOf(b.pos)||b.skill-a.skill:transferSort==='fee'?transferFee(a)-transferFee(b):transferSort==='name'?a.name.localeCompare(b.name):b.skill-a.skill);
 const sells=[...c.squad].sort((a,b)=>order.indexOf(a.pos)-order.indexOf(b.pos)||b.skill-a.skill||a.name.localeCompare(b.name));
 return card('SCOUT’S TRANSFER SHORTLIST',`<div class="notice">Transfer funds: <strong>${money(c.budget)}</strong> · Cash ${money(c.money)} · Credit allowance ${money(staffCreditLimit(c))} · Available signing headroom ${money(Math.max(0,c.money+staffCreditLimit(c)))} · Week ${game.round+1} · The scout selects six players based on team needs, affordability, and free-agent youth. Refreshes each matchweek. Players and valuations are fictional.</div><div class="squad-toolbar"><label>Position <select id="transferpos">${['ALL','GK','DEF','MID','FWD'].map(s=>`<option value="${s}" ${transferPos===s?'selected':''}>${s==='ALL'?'All positions':s}</option>`).join('')}</select></label><label>Sort by <select id="transfersort">${[['ability','Highest ability'],['position','Position'],['fee','Lowest fee'],['name','Player name']].map(([s,l])=>`<option value="${s}" ${s===transferSort?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="scroll"><table><thead><tr><th>Player</th><th>Position</th><th>Age</th><th>Ability</th><th>Scout’s verdict</th><th>Current status / club</th><th>Transfer fee</th><th></th></tr></thead><tbody>${candidates.map(p=>`<tr>${cell(esc(p.name))}${cell(p.pos)}${cell((p.age??'–')+(game.careerMode==='historical'&&p.historicalVerified&&p.ageEstimated?'~':''),'num')}${cell(p.skill,'num')}${cell(esc(p.scoutReason||'Available'))}${cell(esc(marketOrigin(p)))}${cell(marketPrice(p),'num')}<td><button data-buy="${p.id}" ${p.signed||!transferAffordability(c,p).affordable?`disabled title="${p.signed?'Already signed':esc(transferAffordability(c,p).reason)}"`:""}>${p.signed?'SIGNED':'SIGN'}</button></td></tr>`).join('')||'<tr><td colspan="6">No scout recommendations match that position this week.</td></tr>'}</tbody></table></div><h3 id="sell-release">YOUR SQUAD — SELL OR RELEASE PLAYERS</h3><p class="hint">Scroll below the scout shortlist to find RELEASE beside each squad player. A sale requires an interested club. Alternatively, release a player onto the free-transfer list; terminating the contract costs ten weeks of wages and earns no transfer fee. The minimum squad size is 16.</p><div class="scroll"><table><thead><tr><th>Player</th><th>Position</th><th>Age</th><th>Ability</th><th>Interested club</th><th>Fee</th><th>Actions</th></tr></thead><tbody>${sells.map(p=>{const buyers=game.clubs.filter(x=>x.id!==c.id&&x.division>=Math.max(0,c.division-1)&&x.money+p.value>=0&&x.budget>=p.value);const buyer=(p.id+game.round)%4===0?null:buyers[(p.id+game.round)%buyers.length];return `<tr>${cell(esc(p.name))}${cell(p.pos)}${cell((p.age??'–')+(game.careerMode==='historical'&&p.historicalVerified&&p.ageEstimated?'~':''),'num')}${cell(p.skill,'num')}${cell(esc(buyer?.name||'No offers'))}${cell(buyer?money(p.value):'—','num')}<td><button data-sell="${p.id}" data-buyer="${buyer?.id??''}" ${c.squad.length<=16||!buyer?'disabled':''}>SELL</button> <button class="secondary" data-release="${p.id}" ${c.squad.length<=16||c.money-(p.wage||0)*10 < -staffCreditLimit(c)?'disabled':''} title="Costs 10 weeks wages: ${money((p.wage||0)*10)}">RELEASE · ${money((p.wage||0)*10)}</button></td></tr>`;}).join('')}</tbody></table></div><h3>TRANSFER LEDGER</h3><div class="scroll"><table><thead><tr><th>Player</th><th>From</th><th>To</th><th>Fee / release cost</th></tr></thead><tbody>${(game.transferHistory||[]).slice(0,30).map(x=>`<tr>${cell(esc(x.player))}${cell(esc(x.from))}${cell(esc(x.to))}${cell(x.action==='release'?'Released · '+money(x.compensation):money(x.fee),'num')}</tr>`).join('')||'<tr><td colspan="4">No transfers yet.</td></tr>'}</tbody></table></div>`);
}
function shooting(){return card('RETRO PLUS — SHOT PRACTICE',`<p>Choose where to shoot. This is an optional arcade practice mode and <strong>does not affect league or cup results</strong>.</p><div class="pitch"><span class="player" id="keeper" style="left:85%;top:42%">🧤</span><span class="player" id="ball" style="left:19%;top:42%">⚽</span><div class="goal"></div></div><div class="controls"><button data-shot="left">↖ LEFT</button><button data-shot="centre">↑ CENTRE</button><button data-shot="right">↗ RIGHT</button></div><div class="notice" id="shotresult">${shot.score} goals from ${shot.attempts} shots</div><p id="shotmessage">Aim your shot!</p>`);}
function saves(){return card('SAVE / LOAD',`<p>Your current career is stored locally in this browser. Export a JSON backup before starting a new game or switching football worlds.</p><div class="controls"><button data-action="export">EXPORT CAREER (.JSON)</button><label class="btn" for="importfile">IMPORT CAREER</label><input type="file" id="importfile" accept=".json,application/json" style="display:none"></div><div class="controls"><button class="secondary" data-nav="newgame">NEW GAME — CHOOSE FOOTBALL WORLD</button></div><p class="hint">The 92-club simulation is local to your browser. No server or account is required.</p>`);}
function manager(){
 const m=game.manager||{},c=game.clubs[m.clubId]||me(),offers=m.offers||[],summary=careerSummary(game),opportunities=game.clubs.filter(x=>x.id!==m.clubId&&(m.employed?x.division>=Math.max(0,c.division-1):x.division>=2)).slice(0,18);
 const ledger=summary.teams.map(t=>`<tr>${cell(esc(t.name))}${cell(t.played,'num')}${cell(t.won,'num')}${cell(t.drawn,'num')}${cell(t.lost,'num')}${cell(t.for,'num')}${cell(t.against,'num')}</tr>`).join('');
 const appointments=(m.career||[]).map(j=>`<div class="event">${esc(game.clubs[j.clubId]?.name||'Unknown')} · ${j.season} · Week ${j.week}: ${esc(j.reason)}</div>`).join('');
 const achievements=summary.honours.map(h=>`<div class="event">🏆 ${h.season}–${String(h.season+1).slice(-2)} · ${esc(game.clubs[h.clubId]?.name||'Club')} — ${esc(h.title)}</div>`).join('');
 const record=summary.total;
 return card('MANAGER’S OFFICE',`<div class="stats">${[['YOUR STATUS',m.employed?'EMPLOYED':'UNEMPLOYED'],['CLUB',m.employed?c.name:'Seeking appointment'],['REPUTATION',(m.reputation??45)+'/100'],['BOARD CONFIDENCE',m.employed?(m.security??65)+'/100':'—']].map(([k,v])=>`<div class="stat"><span class="label">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>
 <h3>CAREER RECORD</h3><div class="stats">${[['MATCHES',record.played],['WON',record.won],['DRAWN',record.drawn],['LOST',record.lost],['GOALS FOR',record.for],['GOALS AGAINST',record.against]].map(([k,v])=>`<div class="stat"><span class="label">${k}</span><strong>${v}</strong></div>`).join('')}</div>
 <h3>CLUBS MANAGED</h3><div class="scroll"><table class="career-table"><thead><tr><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th></tr></thead><tbody>${ledger||'<tr><td colspan="7">Your first match is still to come.</td></tr>'}</tbody></table></div>
 ${summary.legacy?'<p class="hint">The verified manager-by-manager record starts with this update. Older saves did not capture every managerial appointment or result; new statistics will accumulate as you play.</p>':''}
 ${summary.legacyClubHistory?.length?`<h3>EARLIER CLUB SEASONS — HISTORICAL SAVE DATA</h3><p class="hint">These are your current club’s saved league records from earlier seasons, not independently verified personal managerial statistics.</p><div class="scroll"><table><thead><tr><th>Season</th><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th></tr></thead><tbody>${summary.legacyClubHistory.map(h=>`<tr>${cell(h.season+'–'+String(h.season+1).slice(-2))}${cell(esc(game.clubs[h.clubId].name))}${cell(h.played)}${cell(h.won)}${cell(h.drawn)}${cell(h.lost)}</tr>`).join('')}</tbody></table></div>`:''}
 <h3>HONOURS & ACCOMPLISHMENTS</h3>${achievements||'<p class="hint">No verified honours recorded yet. League titles, promotions and cup victories are recorded at the end of each season.</p>'}
 <h3>TRANSFER RECORDS</h3><div class="stats">${[['RECORD SIGNING',summary.bought?`${summary.bought.player} · ${money(summary.bought.fee)}`:'No recorded purchases'],['RECORD SALE',summary.sold?`${summary.sold.player} · ${money(summary.sold.fee)}`:'No recorded sales']].map(([k,v])=>`<div class="stat"><span class="label">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>
 <h3>APPOINTMENTS & DEPARTURES</h3>${appointments||`<div class="event">${esc(c.name)} · Current appointment</div>`}
 <div class="controls"><button data-nav="staff">BACKROOM STAFF · HIRE & REPLACE</button><button class="secondary" data-nav="finances">CLUB ACCOUNTS</button></div>
 <p class="hint">Board confidence follows results and league position. Strong performances may attract job offers; poor performances can lead to dismissal.</p>
 <h3>JOB OFFERS</h3>${offers.length?offers.map(o=>`<div class="job-offer"><strong>${esc(game.clubs[o.clubId].name)}</strong><span>${divName(game.clubs[o.clubId].division)}</span><button data-job="${o.clubId}">ACCEPT JOB</button></div>`).join(''):'<p>No offers at present.</p>'}
 <h3>${m.employed?'EXPLORE OTHER CLUBS':'APPLY FOR A JOB'}</h3><div class="scroll"><table><thead><tr><th>Club</th><th>Division</th><th>Action</th></tr></thead><tbody>${opportunities.map(x=>`<tr>${cell(esc(x.name))}${cell(esc(divName(x.division)))}<td><button class="secondary" data-apply="${x.id}">APPLY</button></td></tr>`).join('')}</tbody></table></div>`);
}
function backroom(){
 const profiles=staffReport(game),wages=weeklyStaffWages(game),c=me();
 return card('BACKROOM STAFF — HIRING & REPLACEMENTS',`<div class="notice">You are in the staff recruitment office. The chairman approves staffing decisions. Replacing an employee costs four weeks of the outgoing salary in compensation; your new employee receives a weekly wage. Club cash: <strong>${money(c.money)}</strong> · Chairman-approved overdraft ceiling: <strong>${money(staffCreditLimit(c))}</strong> · Current backroom wages: <strong>${money(wages)}/week</strong>.</div>${[['assistant','Assistant Manager'],['scout','Scout'],['physio','Physiotherapist']].map(([role,label])=>`<h3>${label.toUpperCase()}</h3><div class="book-note"><strong>CURRENT APPOINTMENT: ${esc(profiles[role].title)}</strong><p>${esc(profiles[role].description)}</p><small>Wage: ${money(staffCandidates(game,role)[0]?.severance/4||0)} / week</small></div><div class="scroll"><table><thead><tr><th>Candidate</th><th>Assessment</th><th>Weekly salary</th><th>Compensation</th><th>Decision</th></tr></thead><tbody>${staffCandidates(game,role).map(candidate=>`<tr><td>${esc(candidate.title)}</td><td>${esc(candidate.description)}</td>${cell(money(candidate.wage))}${cell(money(candidate.severance))}<td><button data-hire-role="${role}" data-hire-style="${candidate.style}" ${c.money-candidate.severance < -staffCreditLimit(c)?'disabled title="Beyond permitted overdraft"':''}>APPOINT</button></td></tr>`).join('')}</tbody></table></div>`).join('')}<p class="hint">The physiotherapist's recovery style affects how quickly players return from injury. This is a fictional club economy, not a historical financial reconstruction.</p>`);
}
function finances(){
 const c=me(),e=clubEconomy(game,c),report=accountantReport(game,c),records=(game.financeLedger||[]).filter(x=>x.clubId===c.id).slice(0,18),nextHomeWeek=game.fixtures.findIndex((week,i)=>i>=game.round&&week.some(([home])=>home===c.id)),nextGate=nextHomeWeek<0?0:clubEconomy(game,c,nextHomeWeek).gate;
 return recordSpread('Club Accounts','Accountant Advice',`<div class="page-heading">FINANCIAL REPORT</div><div class="book-subtitle">${esc(c.name)} · THE CLUB LEDGER</div><div class="accountant-report"><div class="accountant-heading">THE CLUB ACCOUNTANT · ${esc(report.name.toUpperCase())}</div><p class="accountant-verdict">“Our finances are <strong>${esc(report.liquidity)}</strong>. ${esc(report.context)} ${esc(report.explanation)}”</p><small>Financial review · ${report.recordedWeeks} recorded matchweeks · Projection, not a historical club account</small></div>
`, `<div class="page-heading">MARGARET'S ADVICE</div><div class="book-subtitle">DECISIONS FOR THE MANAGER</div><div class="book-note"><ol>${report.actions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><div class="controls"><button data-nav="transfers">REVIEW TRANSFERS / WAGES</button><button class="secondary" data-nav="staff">REVIEW BACKROOM COSTS</button><button class="secondary" data-nav="fixtures">VIEW FIXTURE CALENDAR</button></div>
 `, ['19','20'])+card('CLUB ACCOUNTS · FIGURES & LEDGER',`<div class="stats">${[['Cash',money(c.money)],['Transfer funds',money(c.budget)],['Player wages / week',money(e.playerWages)],['Backroom wages / week',money(e.staffWages)],['Estimated next home match income',nextHomeWeek<0?'No remaining home league match':money(nextGate)],['Estimated weekly club income',money(e.commercial+e.success)],['Average home-gate receipts per week',money(report.averageGate)],['Projected current matchweek net',money(e.net)],['Estimated match attendance',e.attendance?e.attendance.toLocaleString('en-GB'):'Away / no fixture'],['Supporter mood',supporterMood(ensureSupporters(game,c).confidence)]].map(([a,b])=>`<div class="stat"><span class="label">${a}</span><strong>${b}</strong></div>`).join('')}</div>
 <p class="hint">Fictional 1989-flavoured finances. Home match income varies with club size, quality and form; season-end distributions depend on finishing position. No stadium or ticket-price management.</p>
 <div class="controls"><button data-nav="staff">HIRE / REPLACE ASSISTANT, SCOUT OR PHYSIO</button><button class="secondary" data-nav="manager">MANAGER’S CAREER</button></div>
 <h3>RECENT CLUB ACCOUNTS</h3><p class="hint">An away match has no home gate receipts. Past accounts are left unchanged; new entries distinguish home gates, away matches and weeks without a league fixture.</p><div class="scroll"><table><thead><tr><th>Season / Week</th><th>Entry</th><th>Details</th><th>Net</th></tr></thead><tbody>${records.map(x=>`<tr>${cell(x.season+' / '+x.week)}${cell(esc(x.type))}${cell(esc(x.note))}${cell(money(x.amount),'num')}</tr>`).join('')||'<tr><td colspan="4">The accounts ledger will start recording after your next matchweek.</td></tr>'}</tbody></table></div>`);
}
function render(){if(!game){app.innerHTML=welcome();return;}app.innerHTML=nav()+({notebook,retro:retroMenu,home:office,ground:()=>{notebookPage='ground';return groundNotebook();},supporters:()=>{notebookPage='supporters';return supporterNotebook();},manager,squad,league,fixtures,cups,review,transfers,finances,staff:backroom,match,shots:shooting,save:saves,newgame:welcome}[view]||office)();if(view==='fixtures')showFixtures(Math.min(game.round,45));}
function commit(){save();render();}
app.addEventListener('change',e=>{try{const t=e.target;if(t.id==='ticketpolicy'){setTicketPolicy(game,me(),t.value);commit();return;}if(t.id==='groundclub'){groundClubId=Number(t.value);render();return;}if(t.id==='newmode'){const mode=t.value,fiction=fictionalClubNames(newWorldSeed);const dropdown=document.getElementById('newclub');if(dropdown)for(const option of dropdown.options){const c=CLUBS[Number(option.value)];option.textContent=divName(c.division)+' — '+(mode==='alternate'?fiction[c.id]:c.name);}const help=document.getElementById('modehelp');if(help)help.textContent=mode.startsWith('historical')?'HISTORICAL 92-CLUB RESEARCH BETA: season-associated names for all 92 clubs. Import a corrected CSV to override records. Ages from DOB; ratings are estimates. Opening-day candidates require supported club-history dates.':mode==='alternate'?'Documented PES English club aliases where available; original fictional names for other 1989 clubs. Generated players throughout.':'All 92 historical 1989–90 clubs with generated players and ratings.';}else if(t.id==='researchcsv'){const file=t.files?.[0];if(!file){importedResearchRows=null;return;}file.text().then(text=>{importedResearchRows=parseResearchCSV(text);const el=document.getElementById('researchstatus');if(el)el.textContent=importedResearchRows.length+' researched player rows loaded from '+file.name+'. Applied ONLY when starting a new historical career.';}).catch(err=>toast('CSV import: '+err.message));}else if(t.id==='formation'){me().formation=t.value;me().lineup=autoLineup(me());pitchPick=null;commit();}else if(t.id==='tactic'){me().tactic=t.value;commit();}else if(t.dataset.player){const info=toggleStarter(me(),t.dataset.player,t.checked);pitchPick=null;commit();if(info.action==='swapped')toast(`${info.added} replaces ${info.replaced}`);}else if(t.id==='squadsort'){squadSort=t.value;render();}else if(t.id==='squaddirection'){squadDirection=t.value;render();}else if(t.id==='leaguediv'){leagueDivision=Number(t.value);inspectedClubId=null;render();}else if(t.id==='leaguesort'){leagueSort=t.value;render();}else if(t.id==='leagueorder'){leagueOrder=t.value;render();}else if(t.id==='leaguequery'){leagueQuery=t.value;render();}else if(t.id==='scrapbookcategory'){scrapbookCategory=t.value;render();return;}if(t.id==='logcategory'){logCategory=t.value;render();}else if(t.id==='transferpos'){transferPos=t.value;render();}else if(t.id==='transfersort'){transferSort=t.value;render();}else if(t.id==='roundselect')showFixtures(Number(t.value));else if(t.id==='importfile')importSave(t.files[0]);}catch(err){toast(err.message);render();}});
async function importSave(file){if(!file)return;try{if(file.size>8e6)throw Error('Save too large');const g=JSON.parse(await file.text());if(![2,3].includes(g.version)||g.clubs?.length!==92||!Array.isArray(g.fixtures)||g.fixtures.length!==46||!Array.isArray(g.results)||!Number.isInteger(g.selected)||g.selected<0||g.selected>91||!Number.isInteger(g.round)||g.round<0||g.round>46||!g.cups||!Array.isArray(g.history)||!['active','finished'].includes(g.status))throw Error('Unsupported or malformed v1.0 save');if(!confirm('Replace current career with this save?'))return;if(g.careerMode==='historical'||g.careerMode==='historical-opening')throw Error('Historical-save imports require the separate authorised research build');game=upgradeSave(g);reportIndex=(game.matchReports||[]).length-1;commit();toast('Career imported!');}catch(err){toast('Import failed: '+err.message);}}
function stopReplay(){if(replayTimer!==null){clearInterval(replayTimer);replayTimer=null;}stopRetroScene();}
function replayStep(){const r=gameReport(),box=document.getElementById('events');if(!r||!box||replayIndex>=r.events.length){stopReplay();return;}const e=r.events[replayIndex++];if(watch){const [hs,as]=replayScore(r,replayIndex);const scoreboard=document.getElementById('live-score'),clock=document.getElementById('live-clock');if(scoreboard)scoreboard.textContent=`${hs} – ${as}`;if(clock)clock.textContent=`${e.minute}′ · ${e.type.toUpperCase()}`;if(e.type==='fulltime'){watch=false;document.getElementById('replay-detail')?.removeAttribute('hidden');}}box.querySelectorAll('.timeline-item').forEach((el,i)=>{el.classList.toggle('current',i===replayIndex-1);el.setAttribute('aria-current',i===replayIndex-1?'true':'false');});const focus=document.getElementById('matchfocus');if(focus){const icons={goal:'⚽',chance:'🎯',yellow:'🟨',injury:'✚',kickoff:'📣',halftime:'⏸',fulltime:'🏁'};focus.className='match-focus '+(e.type==='goal'?'match-focus-goal':'');focus.innerHTML=`<div class="match-focus-icon">${icons[e.type]||'📻'}</div><strong>${e.minute}′ · ${esc(e.type.toUpperCase())}</strong><p>${esc(e.text)}</p><small>${Number.isInteger(e.team)?reportTeam(e.team):'Project 1989 Match Centre'}</small>`;}drawRetroScene(document.getElementById('retrocanvas'),{...r,homeShirt:clubColoursById(game.clubs,r.home),venue:r.venue||groundProfile(game.clubs[r.home]).name,night:r.night??(r.week%5===0),groundSnapshot:r.groundSnapshot||game.clubs[r.home]?.ground},{...e,scoreText:watch?replayScore(r,replayIndex).join(' - '):`${r.hg} - ${r.ag}`});if(replayIndex>=r.events.length){if(replayTimer!==null){clearInterval(replayTimer);replayTimer=null;}}}
function replay(){stopReplay();replayIndex=0;if(!watch){watch=true;render();}const box=document.getElementById('events');if(!box)return;replayStep();replayTimer=setInterval(replayStep,Number(document.getElementById('replayspeed')?.value||1450));}
function fullEvents(){stopReplay();watch=false;document.getElementById('replay-detail')?.removeAttribute('hidden');const score=document.getElementById('live-score'),rpt=gameReport();if(score&&rpt)score.textContent=`${rpt.hg} – ${rpt.ag}`;const r=gameReport(),box=document.getElementById('events');if(!r||!box)return;box.querySelectorAll('.timeline-item').forEach(el=>el.classList.remove('current'));const focus=document.getElementById('matchfocus');if(focus)focus.innerHTML='<strong>FULL MATCH COMMENTARY</strong><div class="commentary-scroll">'+r.events.map(eventHTML).join('')+'</div>';replayIndex=r.events.length;}

app.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;try{if(t.dataset.editionVoice){editionVoice=t.dataset.editionVoice;render();return;}if(t.dataset.programme!==undefined){selectedProgrammeId=t.dataset.programme||null;openNotebookPage('programme');return;}if(t.dataset.seasonEdition){editionSeason=Number(t.dataset.seasonEdition);render();return;}if(t.dataset.nav){setView(t.dataset.nav);return;}if(t.dataset.desk){deskCategory=t.dataset.desk;render();document.getElementById('desk-drawer')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}if(t.dataset.inspectClub!==undefined){inspectedClubId=Number(t.dataset.inspectClub);view='league';render();return;}if(t.dataset.incident!==undefined){stopReplay();replayIndex=Number(t.dataset.incident);replayStep();return;}if(t.dataset.book){openNotebookPage(t.dataset.book);return;}if(t.dataset.story){selectedStoryId=t.dataset.story;markStoryRead(game,selectedStoryId);commit();return;}if(t.dataset.storyRead){markStoryRead(game,t.dataset.storyRead);commit();return;}if(t.dataset.storyChoice){const item=answerStory(game,t.dataset.storyId,t.dataset.storyChoice);commit();toast(item.outcome);return;}if(t.dataset.pitch){pitchPick=Number(t.dataset.pitch);render();return;}if(t.dataset.replace){const info=swapPlayers(me(),Number(t.dataset.replace),pitchPick);pitchPick=null;commit();toast(`${info.added} replaces ${info.replaced}`);return;}if(t.dataset.hireRole){if(!confirm('Ask the chairman to approve this appointment and compensation?'))return;const result=hireStaff(game,t.dataset.hireRole,t.dataset.hireStyle);commit();toast('Chairman approves: '+result.title);return;}if(t.dataset.buy){const result=transact(game,t.dataset.buy,'buy');commit();toast(`${result.player}: ${result.from} → ${result.to}`);return;}if(t.dataset.release){const p=me().squad.find(p=>p.id===Number(t.dataset.release));if(!p)return;const cost=(p.wage||0)*10;if(confirm(`Release ${p.name} on a free transfer? Compensation £${cost.toLocaleString('en-GB')} (10 weeks' wages). No transfer fee will be received.`)){const result=transact(game,t.dataset.release,'release');commit();toast(`${result.player} released; compensation £${result.compensation.toLocaleString('en-GB')}`);}return;}if(t.dataset.sell){if(confirm('Confirm this sale to '+game.clubs[Number(t.dataset.buyer)].name+'?')){const result=transact(game,t.dataset.sell,'sell',t.dataset.buyer);commit();toast(`${result.player}: ${result.from} → ${result.to}`);}return;}if(t.dataset.job){acceptJob(game,t.dataset.job);view='notebook';commit();return;}if(t.dataset.apply){const granted=applyForJob(game,t.dataset.apply);commit();toast(granted?'Job offer received!':'Application unsuccessful');return;}if(t.dataset.shot){const r=rng(Date.now()+shot.attempts*73),direction=t.dataset.shot,keeper=['left','centre','right'][Math.floor(r()*3)],goal=keeper!==direction||r()>.55;shot.attempts++;if(goal)shot.score++;document.getElementById('keeper').style.top=keeper==='left'?'16%':keeper==='right'?'68%':'40%';document.getElementById('ball').style.left='88%';document.getElementById('ball').style.top=direction==='left'?'16%':direction==='right'?'68%':'40%';document.getElementById('shotresult').textContent=`${shot.score} goals from ${shot.attempts} shots`;document.getElementById('shotmessage').textContent=goal?'GOAL!':'SAVED!';return;}switch(t.dataset.action){case 'ground-light':groundNight=!groundNight;render();break;case 'collect-programme':{const fx=currentHomeFixture(game);if(!fx)throw Error('No current home fixture to collect');const item=collectProgramme(game,programmeForFixture(game,...fx));selectedProgrammeId=item.id;commit();toast('Programme pasted into the Manager’s Scrapbook.');break;}case 'programme-png':case 'programme-pdf':{const archived=programmeArchive(game).find(p=>p.id===selectedProgrammeId);const fx=currentHomeFixture(game);const p=archived||(fx?programmeForFixture(game,...fx):programmeArchive(game).at(-1));if(!p)throw Error('No matchday programme available');downloadProgramme(p,game.clubs[p.homeId],clubColoursById(game.clubs,p.homeId),t.dataset.action==='programme-png'?'png':'pdf').catch(err=>toast('Export failed: '+err.message));break;}case 'build-ground':{const key=document.getElementById('groundproject')?.value;if(!key)throw Error('No improvement available');const type=PROJECTS[key],method=document.getElementById('groundmethod')?.value||'now';if(!confirm(`Approve ${type.name} for ${money(projectPrice(me(),key,method))}? ${method==='summer'?'The work will be completed in the close season, ready for next season.':'Work begins now, taking '+type.weeks+' matchweeks and temporarily reducing matchday access.'}`))return;const project=startProject(game,me(),key,method);commit();toast(`${project.name} approved — ${method==='summer'?'scheduled for summer completion':project.weeksLeft+' weeks remaining'}.`);break;}case 'recalibrate-historical':{if(!confirm('Update researched players to the new individual 1989 ability estimates? This changes abilities and potentials, not names, ages, results or squad registrations. Export a backup first.'))return;const n=recalibrateHistoricalRatings(game);commit();toast(n+' researched player ratings repaired.');break;}case 'backleague':inspectedClubId=null;render();break;case 'repair-fixtures':{if(!confirm('Rebalance all REMAINING home and away league fixtures? Completed results, opponents and matchweeks will not change. Export a backup first.'))return;const count=rebalanceRemainingFixtures(game);commit();toast(count+' fixture pairs rebalanced.');break;}case 'new':if(game&&!confirm('Start a NEW career? This replaces your current browser save. Export a JSON backup using Save / Load first if you want to keep the current career.'))return;{const mode=document.getElementById('newmode')?.value||'fictional';game=newGame(Number(document.getElementById('newclub').value),newWorldSeed,mode);if(mode.startsWith('historical')&&importedResearchRows){const result=applyHistoricalResearch(game,importedResearchRows,mode==='historical-opening');game.historicalCoverage='Imported user research: '+result.accepted+' records applied; unverified and missing clubs still generated. Ratings simulated.';game.messages.unshift('Historical CSV imported: '+result.accepted+' player records applied to starting squads.');}}reportIndex=0;watch=false;notebookPage='desk';view='retro';commit();break;case 'resume':{const stored=JSON.parse(localStorage.getItem(KEY));if(!stored)throw Error('Unsupported save');if(stored.careerMode==='historical'||stored.careerMode==='historical-opening')throw Error('This public tester package cannot open historical-data saves; use the private research build');game=upgradeSave(stored);setView('retro');break;}case 'autolineup':me().lineup=autoLineup(me());pitchPick=null;commit();break;case 'assistantlineup':me().lineup=assistantLineup(me(),staffReport(game).assistant);pitchPick=null;commit();toast('Assistant Manager has selected the match-ready XI.');break;case 'cancelpick':pitchPick=null;render();break;case 'play':case 'watch':{if(!game.manager?.employed)throw Error('You need a club appointment first');if(!validLineup(me()))throw Error('Your team selection is invalid');stopReplay();watch=t.dataset.action==='watch';advanceRound(game);reportIndex=(game.matchReports||[]).length-1;commit();if(watch)setTimeout(replay,120);break;}case 'showevents':replay();break;case 'replay':replay();break;case 'next-event':stopReplay();if(!watch){watch=true;render();replayIndex=0;}replayStep();break;case 'all-events':fullEvents();break;case 'stop-replay':stopReplay();break;case 'prevreport':stopReplay();reportIndex=Math.max(0,reportIndex-1);watch=false;render();break;case 'nextreport':stopReplay();reportIndex=Math.min((game.matchReports||[]).length-1,reportIndex+1);watch=false;render();break;case 'advance-unemployed':if(game.manager?.employed)throw Error('You are already employed');advanceRound(game);reportIndex=(game.matchReports||[]).length-1;commit();break;case 'nextseason':if(game.status!=='finished')throw Error('Season is not finished');newSeason(game);reportIndex=0;watch=false;view='home';commit();break;case 'export':{const blob=new Blob([JSON.stringify(game,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`project-1989-${game.season}-week-${game.round}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000);break;}}}catch(err){toast(err.message);render();}});
try{const value=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(PREVIOUS));if(value?.clubs?.length===92&&value.careerMode!=='historical'&&value.careerMode!=='historical-opening'){game=upgradeSave(value);reportIndex=(game.matchReports||[]).length-1;save();}}catch{console.warn('Invalid browser save');}render();
